begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'PE_PLAN_SAFE_ACTIVITY';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Planejar atividades de movimento com segurança e acesso', 'Um plano seguro começa pelo contexto: espaço, circulação, materiais, supervisão e alternativas. A turma não precisa seguir um único ritmo nem expor informações de saúde. A experiência física é mediada pelo professor; a atividade digital trabalha planejamento, sem prescrever exercício pessoal ou avaliar aptidão.', '## Comece pelo ambiente
Antes de uma proposta, observe piso, obstáculos, circulação, materiais, clima e supervisão. Uma mudança de local exige nova checagem: o plano não continua automaticamente seguro em qualquer espaço.

## Planeje escolhas e adaptações
Uma proposta acessível permite formas diferentes de participação e uma alternativa equivalente, como observar e registrar estratégias. Pergunte sobre a atividade, não sobre diagnóstico, peso, condição de saúde ou rotina familiar. Ninguém deve ser pressionado a demonstrar movimento.

## Combine comunicação e pausas
O professor explica como pedir pausa e como chamar ajuda. Se alguém relata mal-estar, interrompe a participação e comunica o adulto responsável, seguindo o protocolo da escola; colegas não diagnosticam. Esta lição não prescreve intensidade, duração ou tratamento individual.

## Exemplo resolvido
A quadra está indisponível. O grupo não ocupa automaticamente o corredor: consulta o professor, verifica uma sala livre, circulação, piso e acessibilidade, propõe opções e combina sinal de pausa. Se nenhum espaço for adequado, adiar é uma decisão segura.',
    'Revise um plano de caminhada quando começa a chover. 1) Pare antes de transferir a atividade. 2) Consulte o professor. 3) Verifique piso, circulação e acessibilidade do espaço alternativo. 4) Ofereça opção equivalente e possibilidade de adiamento. 5) Registre a razão da escolha sem atribuir culpa a participantes.', array['Observe o contexto e o propósito, não apenas o nome do movimento.', 'Planeje opções seguras e acessíveis com mediação do professor.', 'A atividade digital verifica compreensão e planejamento, não aptidão física.']::text[], 25, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"pe-plan-safe-activity","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer movimentos corporais em situações cotidianas.","Descrever espaço, regras e escolhas em uma atividade."],"key_concepts":["Atividade física é uma categoria ampla de movimento.","Exercício físico é planejado, estruturado e repetido com propósito.","Segurança, acesso, escolha e adaptação fazem parte do planejamento."],"progression":[{"stage":"FOUNDATION","focus":"Identificar o contexto, o planejamento e o propósito de uma situação.","questionIds":["v5-pe-safe-plan-probe-01","v5-pe-safe-plan-practice-01"]},{"stage":"APPLICATION","focus":"Planejar uma opção e justificar cuidados e adaptações.","questionIds":["v5-pe-safe-plan-practice-02","v5-pe-safe-plan-transfer-01","v5-pe-safe-plan-lock-01"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Revisar uma proposta diante de um novo contexto ou barreira.","questionIds":["v5-pe-safe-plan-review-01"]}],"micro_explanations":[{"trigger":"CHECK_ENVIRONMENT","text":"Antes de começar ou mudar de espaço, confira piso, obstáculos, circulação, materiais e supervisão."},{"trigger":"ACCESS_IS_PART_OF_PLAN","text":"Planeje mais de uma forma de participar; escolha e acessibilidade não são exceções improvisadas."},{"trigger":"PAUSE_AND_TELL_ADULT","text":"Diante de mal-estar, pare a participação e avise o professor. Não peça que colegas façam diagnóstico."},{"trigger":"NO_PERSONAL_HEALTH_DISCLOSURE","text":"Uma adaptação não deve exigir que o estudante exponha diagnóstico ou histórico de saúde à turma."}],"remediations":[{"id":"pe-safe-remediate-space","misconception":"ENVIRONMENT_IGNORED","prompt":"Faça uma lista de espaço, piso, obstáculos, circulação e supervisão. Marque o que o professor precisa verificar antes de decidir."},{"id":"pe-safe-remediate-uniformity","misconception":"ONE_FORM_FOR_ALL","prompt":"Escreva duas opções equivalentes de participação e escolha uma que não exija explicar informações de saúde."},{"id":"pe-safe-remediate-signal","misconception":"PUSH_THROUGH_SIGNAL","prompt":"Reordene as ações: parar, comunicar o adulto responsável e seguir o protocolo escolar. Retire diagnósticos e pressão por desempenho."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: Glossary of Terms","publisher":"World Health Organization","url":"https://www.ncbi.nlm.nih.gov/books/NBK566047/","accessedOn":"2026-10-13","supports":["Exercício é subcategoria de atividade física planejada, estruturada e repetitiva com propósito definido."],"use":"Checagem conceitual para diferenciar atividade física e exercício; enunciados, exemplos e atividades deste pacote são autorais."},{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: Children and Adolescents","publisher":"World Health Organization","url":"https://www.who.int/publications/i/item/9789240015128","accessedOn":"2026-10-13","supports":["Atividade física juvenil pode ocorrer em lazer, educação física, transporte e tarefas; oportunidades devem ser seguras, equitativas, agradáveis e adequadas à idade e capacidade."],"use":"Fundamenta variedade, segurança e acessibilidade; não é usado para prescrever dose ou rotina individual."},{"title":"Guia de Atividade Física para a População Brasileira","publisher":"Ministério da Saúde","url":"https://bvsms.saude.gov.br/bvs/publicacoes/guia_atividade_fisica_populacao_brasileira.pdf","accessedOn":"2026-10-13","supports":["Orientações brasileiras para atividade física e exercício, inclusive crianças e jovens; distinção de que exercício é uma forma planejada de atividade física."],"use":"Referência pública para contexto e linguagem; os pacotes não reproduzem o guia nem formulam recomendação clínica."}],"copyright_note":"Questões e propostas de atividade são autorais. Fontes oficiais fundamentam conceitos e salvaguardas, mas não equivalem a validação do percurso ou aprovação curricular. Mapeamento e revisão pedagógica permanecem pendentes.","authentic_activities":[{"id":"v5-pe-safe-activity-plan-audit","title":"Revisão de segurança e participação","objective":"Produzir e revisar um plano escolar de movimento com checagem do ambiente, alternativa acessível e comunicação de pausa.","context":"Planejamento em grupo a partir de um cenário fictício de aula, com implementação opcional somente se o professor avaliar o espaço e autorizar.","materials":["Mapa simples ou desenho de um espaço escolar fictício","Cartões de mudanças de contexto (chuva, circulação, material indisponível)","Quadro de checagem de acesso, supervisão, pausa e alternativas"],"instructions":"Escolha um cenário fictício e desenhe um plano de movimento. Marque obstáculos, circulação, supervisão, materiais, uma alternativa equivalente e como qualquer participante pode pedir pausa. Em seguida, sorteie uma mudança de contexto e revise o plano. O professor decide se alguma vivência é apropriada; ela é voluntária e substituível por planejamento em papel. Não registrar esforço, medidas corporais, saúde ou desempenho individual.","evidence":"Plano visual revisado com condições verificadas, duas formas de participação, regra clara de pausa/comunicação e justificativa da decisão de realizar, adaptar ou adiar.","safety":"Não executar atividade sem aprovação docente do espaço, materiais e condições locais. Evitar obstáculos, competição de resistência, prescrição de intensidade e qualquer exigência de participação corporal. Seguir os protocolos escolares e interromper ao receber relato de desconforto.","privacyGuard":"Não coletar diagnóstico, deficiência, peso, medidas, frequência cardíaca, sintomas, imagens, rotina de exercício ou justificativas familiares. O aluno pode usar um cenário inteiramente fictício.","ageRange":"6º e 7º anos do Ensino Fundamental, com mediação docente.","mediation":"O professor valida o contexto local antes de qualquer execução, assegura alternativas equivalentes e avalia a qualidade do planejamento, não a aptidão ou disposição física dos estudantes.","rubric":[{"criterion":"Leitura do contexto e riscos","emerging":"Não identifica mudança no ambiente ou obstáculos relevantes.","developing":"Identifica um fator de segurança com orientação.","proficient":"Verifica ambiente, circulação, materiais e supervisão antes de decidir."},{"criterion":"Acesso e escolhas","emerging":"Prevê uma forma obrigatória de participação.","developing":"Acrescenta alternativa após mediação.","proficient":"Prevê opções equivalentes e preserva escolha sem exigir divulgação de saúde."},{"criterion":"Pausa e revisão","emerging":"Pressiona a continuidade diante de desconforto.","developing":"Inclui pausa depois de pergunta orientadora.","proficient":"Define como parar e comunicar o adulto, e revisa ou adia o plano quando o contexto muda."}]}],"objective":"Planejar uma proposta escolar de movimento que considere espaço, supervisão, escolha, adaptação, pausa e resposta a sinais de desconforto.","common_mistake":"Achar que uma atividade é segura apenas porque é curta; transferir o plano sem rever o espaço; impor ritmo igual; interpretar pausas como falta de esforço; pedir que estudantes revelem informações pessoais para receber uma adaptação.","estimated_minutes":25}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'pe-plan-safe-activity' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-pe-safe-plan-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY_HAZARD","contextFamily":"CLEAR_SPACE","statement":"Antes de uma atividade de movimento, o grupo encontra mochilas espalhadas no espaço. Qual é o primeiro cuidado?","options":["Parar o início, organizar o espaço com o professor e confirmar uma área livre.","Começar depressa para terminar antes.","Pedir que alguém desvie dos obstáculos enquanto o grupo se move.","Ignorar as mochilas se a atividade for curta."],"correctAnswer":"Parar o início, organizar o espaço com o professor e confirmar uma área livre.","explanation":"Um espaço obstruído pode causar tropeços; a turma deve organizar a área com supervisão antes de iniciar.","hint":"Observe primeiro o espaço e peça apoio docente para retirar obstáculos.","errorFocus":"Ignorar risco ambiental em favor de começar logo","misconceptions":{"Começar depressa para terminar antes.":["START_WITH_OBSTACLES"],"Pedir que alguém desvie dos obstáculos enquanto o grupo se move.":["INDIVIDUAL_AVOIDANCE_ONLY"],"Ignorar as mochilas se a atividade for curta.":["SHORT_MEANS_SAFE"]},"position":1},{"id":"v5-pe-safe-plan-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CHOOSE_OPTION","contextFamily":"SCHOOL_ACTIVITY_SPACE","statement":"A quadra está fechada e a turma quer se movimentar em outro local da escola. Que plano considera melhor o contexto?","options":["Usar um corredor estreito com circulação de outras turmas.","Escolher com o professor uma área livre e supervisionada, com opções e pausas combinadas.","Exigir que todos mantenham o mesmo ritmo.","Continuar mesmo quando alguém pede pausa."],"correctAnswer":"Escolher com o professor uma área livre e supervisionada, com opções e pausas combinadas.","explanation":"Área, circulação, supervisão e escolha precisam ser verificadas antes da atividade.","hint":"Confira espaço, pessoas circulando, alternativas e como pedir pausa.","errorFocus":"Ignorar circulação, escolha e sinais de desconforto","misconceptions":{"Usar um corredor estreito com circulação de outras turmas.":["NARROW_BUSY_CORRIDOR"],"Exigir que todos mantenham o mesmo ritmo.":["ONE_PACE_FOR_ALL"],"Continuar mesmo quando alguém pede pausa.":["NO_PAUSE"]},"position":1},{"id":"v5-pe-safe-plan-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"WEATHER_CHANGE","statement":"Uma proposta ao ar livre não pode ocorrer por causa da chuva. Qual é uma revisão segura do plano?","options":["Usar o piso molhado para uma corrida.","Mover a atividade sem verificar o novo local.","Escolher com o educador uma alternativa interna adequada ou adiar, verificando espaço e acesso.","Cancelar toda atividade de movimento para sempre."],"correctAnswer":"Escolher com o educador uma alternativa interna adequada ou adiar, verificando espaço e acesso.","explanation":"Mudar de espaço exige reavaliar piso, circulação, supervisão e acessibilidade; adiar pode ser uma escolha adequada.","hint":"Reavalie as condições antes de transferir a atividade para outro lugar.","errorFocus":"Supor que o plano continua seguro após mudar o ambiente","misconceptions":{"Usar o piso molhado para uma corrida.":["WET_FLOOR_RUN"],"Mover a atividade sem verificar o novo local.":["NO_NEW_SPACE_CHECK"],"Cancelar toda atividade de movimento para sempre.":["NEVER_MOVE_AGAIN"]},"position":1},{"id":"v5-pe-safe-plan-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"RESPOND_TO_SIGNAL","contextFamily":"DIZZINESS_SIGNAL","statement":"Durante uma atividade, uma pessoa relata tontura. Qual resposta é apropriada na aula?","options":["Mandar continuar até o fim para não atrasar o grupo.","Pedir aos colegas que descubram a causa médica.","Transformar a situação em disputa para ver quem aguenta mais.","Interromper a participação dela, avisar o professor e seguir o protocolo de segurança da escola."],"correctAnswer":"Interromper a participação dela, avisar o professor e seguir o protocolo de segurança da escola.","explanation":"Tontura pede pausa e comunicação ao adulto responsável; colegas não devem diagnosticar nem pressionar a pessoa.","hint":"Priorize parar e avisar o professor, sem tentar diagnosticar.","errorFocus":"Desempenho sobreposto à segurança ou diagnóstico entre pares","misconceptions":{"Mandar continuar até o fim para não atrasar o grupo.":["PUSH_THROUGH_SIGNAL"],"Pedir aos colegas que descubram a causa médica.":["PEER_DIAGNOSIS"],"Transformar a situação em disputa para ver quem aguenta mais.":["ENDURANCE_CONTEST"]},"position":1},{"id":"v5-pe-safe-plan-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"REVISE_PLAN","contextFamily":"ACCESS_ALTERNATIVE","statement":"Um plano prevê uma única atividade em pé, mas a escola precisa oferecer participação por diferentes meios. Qual revisão melhora o plano?","options":["Consultar o grupo e preparar opções equivalentes, como versão sentada, observação ativa ou registro da estratégia.","Manter a regra para todos, sem exceção.","Retirar da atividade quem não fizer do modo original.","Pedir que cada pessoa explique sua condição de saúde para a turma."],"correctAnswer":"Consultar o grupo e preparar opções equivalentes, como versão sentada, observação ativa ou registro da estratégia.","explanation":"Opções equivalentes ampliam participação; não é necessário exigir divulgação de informação pessoal.","hint":"Troque uma forma única por escolhas que preservem o objetivo pedagógico.","errorFocus":"Confundir uniformidade com equidade e exigir exposição","misconceptions":{"Manter a regra para todos, sem exceção.":["ONE_FORM_FOR_ALL"],"Retirar da atividade quem não fizer do modo original.":["EXCLUDE_DIFFERENCE"],"Pedir que cada pessoa explique sua condição de saúde para a turma.":["FORCED_HEALTH_DISCLOSURE"]},"position":1},{"id":"v5-pe-safe-plan-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ORGANIZE_MATERIALS","contextFamily":"SHARED_EQUIPMENT","statement":"Uma turma tem poucos materiais para uma atividade planejada. Qual ajuste considera participação e segurança?","options":["Lançar os materiais todos ao mesmo tempo em um espaço apertado.","Organizar estações ou turnos com espaço livre, regras claras e alternativas para quem aguarda.","Excluir quem não conseguiu pegar o material primeiro.","Aumentar a velocidade para que a turma termine logo."],"correctAnswer":"Organizar estações ou turnos com espaço livre, regras claras e alternativas para quem aguarda.","explanation":"Turnos e espaço organizado reduzem colisões e permitem participação; o professor verifica se a proposta é adequada ao local.","hint":"Pense em circulação, espera e opção de participação antes de aumentar o ritmo.","errorFocus":"Confundir pressa e competição com organização segura","misconceptions":{"Lançar os materiais todos ao mesmo tempo em um espaço apertado.":["CROWDED_EQUIPMENT"],"Excluir quem não conseguiu pegar o material primeiro.":["FIRST_COMES_EXCLUDED"],"Aumentar a velocidade para que a turma termine logo.":["SPEED_OVER_SAFETY"]},"position":2}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'pe-plan-safe-activity',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'pe-plan-safe-activity' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'PHYSICAL_EDUCATION', 'SAUDE', 'planejar atividades de movimento com segurança e acesso',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

commit;
